import{_ as s,E as t,h as i,c as o,b as a,f as r,H as p,a4 as l}from"./chunks/framework.B_fYP6Of.js";const b=JSON.parse('{"title":"Prompts for AI coding partners","description":"Use eight copyable prompts to plan, build, debug, and rehearse an IS373 RAG project. Each one limits the agent’s scope and asks for evidence you can check.","frontmatter":{"title":"Prompts for AI coding partners","description":"Use eight copyable prompts to plan, build, debug, and rehearse an IS373 RAG project. Each one limits the agent’s scope and asks for evidence you can check.","teaser":"When an agent says it fixed your project, which result would convince you? Start with one job and ask for the smallest change you can inspect."},"headers":[],"relativePath":"students/prompts.md","filePath":"students/prompts.md"}'),d={name:"students/prompts.md"};function c(h,e,u,m,g,v){const n=t("LabArticleHeader");return i(),o("div",null,[e[0]||(e[0]=a("h1",{id:"ask-an-ai-coding-agent-for-one-small-result",tabindex:"-1"},[r("Ask an AI coding agent for one small result "),a("a",{class:"header-anchor",href:"#ask-an-ai-coding-agent-for-one-small-result","aria-label":'Permalink to "Ask an AI coding agent for one small result"'},"​")],-1)),p(n),e[1]||(e[1]=l(`<p>Which two terms could you use in a sentence but still have trouble telling apart? Start with those and one passage you’re allowed to share. If you already know what you want to build or debug, skip to the prompt for that task. Replace its brackets with your own files, question and observations.</p><p>Working in your existing FastAPI app? Open the <a href="./from-app-studio">walkthrough</a> first. Considering a new framework? The <a href="./library-survey">library survey</a> can help you decide whether you need one.</p><p><strong>Before you paste a prompt</strong>, decide what would count as success. Give your agent only the approved repository or files it needs. Remove API keys, private records, and credentials. Have it inspect first, propose a small change, and tell you what it actually ran. You choose the design and check the result.</p><h2 id="_1-help-me-understand-without-doing-it-for-me" tabindex="-1">1. Help me understand without doing it for me <a class="header-anchor" href="#_1-help-me-understand-without-doing-it-for-me" aria-label="Permalink to &quot;1. Help me understand without doing it for me&quot;">​</a></h2><p>Use this when you can name what confuses you but still want to make the decision yourself.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I keep mixing up [term A] and [term B]. Here is a passage from my project:</span></span>
<span class="line"><span>[permitted passage and source ID]. Here is what I think each term means:</span></span>
<span class="line"><span>[my explanation]. Use this passage to show the difference. Ask me to</span></span>
<span class="line"><span>identify each one in a second example. Wait for my answer before explaining it.</span></span>
<span class="line"><span>Keep this a discussion and leave my files alone.</span></span></code></pre></div><h2 id="plan-prompt" tabindex="-1">2. Make a bounded Plan <a class="header-anchor" href="#plan-prompt" aria-label="Permalink to &quot;2. Make a bounded Plan {#plan-prompt}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me plan a small, individual RAG app for [reader] using [five permitted sources].</span></span>
<span class="line"><span>I must research vector and graph retrieval but may implement either or both.</span></span>
<span class="line"><span>First ask what my reader needs, what I have already built and where I host.</span></span>
<span class="line"><span>Then compare a keyword baseline, vector and graph for my five questions.</span></span>
<span class="line"><span>Produce: one-sentence scope, source manifest, source-to-answer diagram,</span></span>
<span class="line"><span>selected architecture and reason, two alternatives, five expected-evidence</span></span>
<span class="line"><span>questions including an unanswerable one, and three small acceptance tests.</span></span>
<span class="line"><span>Label all experiments PLANNED. Do not add extra requirements or a new stack.</span></span></code></pre></div><h2 id="_3-add-the-smallest-import-and-inspect-it" tabindex="-1">3. Add the smallest import and inspect it <a class="header-anchor" href="#_3-add-the-smallest-import-and-inspect-it" aria-label="Permalink to &quot;3. Add the smallest import and inspect it&quot;">​</a></h2><p>First confirm which file the agent may read. Compare the stored IDs after the first and second import.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Read my existing project before editing. My authorized input corpus is [path].</span></span>
<span class="line"><span>Add only a small importer with source ID, origin, version and repeat-import</span></span>
<span class="line"><span>handling. Prefer my existing framework/database. Write a test proving that</span></span>
<span class="line"><span>importing the same source twice doesn&#39;t multiply records and a test for a</span></span>
<span class="line"><span>changed source. Explain every table and mutation. Run tests and show exact</span></span>
<span class="line"><span>commands and results. Stop before adding embeddings or chat.</span></span></code></pre></div><h2 id="_4-implement-real-retrieval-not-a-convincing-looking-mock" tabindex="-1">4. Implement real retrieval, not a convincing-looking mock <a class="header-anchor" href="#_4-implement-real-retrieval-not-a-convincing-looking-mock" aria-label="Permalink to &quot;4. Implement real retrieval, not a convincing-looking mock&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>My selected retrieval design is [vector/graph/both], because [reason].</span></span>
<span class="line"><span>My five expected-evidence questions and source IDs are [list].</span></span>
<span class="line"><span>Implement one real end-to-end retrieval slice using my existing storage.</span></span>
<span class="line"><span>Expose the retrieved IDs/passages or supported graph paths before generation.</span></span>
<span class="line"><span>For vectors, use an actual configured embedding model for BOTH corpus and</span></span>
<span class="line"><span>query and record its version; do not invent vectors. Add a keyword baseline</span></span>
<span class="line"><span>and tests for missing/irrelevant evidence. Show the limitations. Do not</span></span>
<span class="line"><span>replace my hosting or implement an unused second database.</span></span></code></pre></div><h2 id="_5-add-generation-and-source-references" tabindex="-1">5. Add generation and source references <a class="header-anchor" href="#_5-add-generation-and-source-references" aria-label="Permalink to &quot;5. Add generation and source references&quot;">​</a></h2><p>Use this after a test can already show the expected retrieved passage. That way you can check generation separately.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Connect my real retrieval result to an available model through server-side</span></span>
<span class="line"><span>configuration [my existing model/provider]. Never put credentials in browser</span></span>
<span class="line"><span>code or logs. Feed only authorized evidence with stable IDs/locations.</span></span>
<span class="line"><span>Present the answer and clickable original references. Include one question</span></span>
<span class="line"><span>my documents cannot answer; report insufficient evidence rather than</span></span>
<span class="line"><span>fabricating a source. Distinguish source retrieval from verified support for</span></span>
<span class="line"><span>each claim. Run actual integration checks, explain untested provider behavior,</span></span>
<span class="line"><span>and avoid reworking unrelated code.</span></span></code></pre></div><h2 id="debug-prompt" tabindex="-1">6. Diagnose a failure without restarting everything <a class="header-anchor" href="#debug-prompt" aria-label="Permalink to &quot;6. Diagnose a failure without restarting everything {#debug-prompt}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me find ONE failure in my existing project.</span></span>
<span class="line"><span>Goal: [expected behavior]. Actual: [redacted error/output].</span></span>
<span class="line"><span>Relevant command: [command]. Environment: [local/CI/hosted].</span></span>
<span class="line"><span>Before editing, propose the most likely cause, the smallest inspection,</span></span>
<span class="line"><span>and how we can prove a fix. Do not delete my database, recreate my server,</span></span>
<span class="line"><span>reset credentials or change DNS. After a bounded fix, rerun the failing</span></span>
<span class="line"><span>check and one related regression check. State what remains unverified.</span></span></code></pre></div><h2 id="_7-make-me-read-and-defend-my-ai-generated-code" tabindex="-1">7. Make me read and defend my AI-generated code <a class="header-anchor" href="#_7-make-me-read-and-defend-my-ai-generated-code" aria-label="Permalink to &quot;7. Make me read and defend my AI-generated code&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Review these specific files: [paths]. Ask me to explain how a source</span></span>
<span class="line"><span>becomes retrieved evidence and reaches the model. Identify the function</span></span>
<span class="line"><span>that owns each database write, how errors propagate, the security boundary,</span></span>
<span class="line"><span>and what happens on a repeat import or failed model call.</span></span>
<span class="line"><span>Give me three code-reading questions and one failing edge case to test.</span></span>
<span class="line"><span>Do not grade my understanding from code alone or claim a check ran unless</span></span>
<span class="line"><span>you actually executed it.</span></span></code></pre></div><h2 id="demo-prompt" tabindex="-1">8. Rehearse the actual course demo <a class="header-anchor" href="#demo-prompt" aria-label="Permalink to &quot;8. Rehearse the actual course demo {#demo-prompt}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Act as a skeptical but kind IS373 demo reviewer. I will show my own</span></span>
<span class="line"><span>portfolio and individual RAG app, then explain my group contribution.</span></span>
<span class="line"><span>For the RAG: ask me to show one permitted source, a real retrieval trace,</span></span>
<span class="line"><span>a real generated answer with reference, and an unanswerable question.</span></span>
<span class="line"><span>Ask which vector/graph architecture I chose and why, and what my peer&#39;s</span></span>
<span class="line"><span>feedback changed. Ask ONE question at a time; never invent my test output.</span></span>
<span class="line"><span>Give constructive feedback using only evidence I actually provide.</span></span></code></pre></div><h2 id="agent-safety-and-ownership" tabindex="-1">Agent safety and ownership <a class="header-anchor" href="#agent-safety-and-ownership" aria-label="Permalink to &quot;Agent safety and ownership&quot;">​</a></h2><p>When you finish, open one file the agent changed, reproduce one result, and describe what the check establishes. Attribute the help you used. Keep your own reflections, actual peer feedback, source permissions, commit history, citations, and test logs grounded in what happened. If you cannot explain a change, ask for a smaller patch. Keep credentials out of the conversation.</p><p><a href="./">Return to the student path</a> · <a href="./check">Check the work</a></p>`,25))])}const y=s(d,[["render",c]]);export{b as __pageData,y as default};
